-- v33: Sonic Jobs V.O.F. company details (KvK 42169998, btw NL870021977B01, Amarantstraat 6, 5044 RK Tilburg) in all 13 templates (version +0.1).
insert into public.legal_templates(id, version, title, audience, effective_date, pdf_path, html_path, sha256, requires_acceptance)
select n.id, n.version, c.title, c.audience, date '2026-10-24', 'legal/'||n.id||'-v'||n.version||'.pdf', 'legal/'||n.id||'.html', n.sha, c.requires_acceptance
from (values ('rider_zzp','0.4','647ecab635b0b4ec119f46b6e18e8d18710b977ac0a2237a51a27d7af03e904c'), ('rider_employment','0.7','177fd221356a829763d0519f193750f0d98b29368a978fc47f01980860d4bc73'), ('restaurant_partner','0.4','fc59b45ecb28ac9248b0bb45aeec72ae5c3c9baeeda51dd100c6ba33176171ea'), ('customer_terms','0.5','e59a905efc5013511e4959c78bd8c599b266adf5734aaad6cb43f44fda7a817e'), ('privacy_statement','0.6','7f8885e3f85a8a8b1c1be8cb1bc22a9bdabac6b360b5be01e4ee448d1bf3554f'), ('dpa_restaurant','0.4','d933a9d11651d17389a0b69ea86485211a0f109d7484e95df72e7f45ea379c01'), ('rider_conduct','0.3','64452e431fa9b7a2147feda388fc7754b120f383ab8cfc27408378ef02cac276'), ('platform_transparency','0.7','dd3f2cd8ba2abade35ac87cc21b4f85f2676730533b0391aaac734b0ac23a2e3'), ('dpia_gps','0.5','87361dc04ac92507212f34c8e4df26a9dcdc2c37299bc02378146effc8e16e9a'), ('processing_register','0.6','07bd57af7bf063102a152057242dc509b5175e735b91468e77c0c76dbc4f8a6c'), ('rider_onboarding','0.5','d01421c9aa21569bc80792cce269837fdfff7fc6563a01fe4eb46ae3a0a8f42c'), ('deactivation_appeal','0.3','6c4cf5864bea2631f47b3049207ca295a56f7720cc903734e571bef17d10afa5'), ('dpa_payroll','0.3','04b9cc62954ec9787335e3a9d409e979e82588aa20e69907c3a15524f96791c7')) n(id, version, sha)
join lateral (select * from public.legal_templates t where t.id = n.id order by string_to_array(t.version,'.')::int[] desc limit 1) c on true
where c.version <> n.version
on conflict (id, version) do update set sha256 = excluded.sha256;
insert into public.legal_acceptances(template_id, version, profile_id, lang, text_sha256, method)
select t.id, t.version, p.id, 'nl', t.sha256, 'test_seed' from public.profiles p join (values ('rider_zzp','0.4','647ecab635b0b4ec119f46b6e18e8d18710b977ac0a2237a51a27d7af03e904c'), ('rider_employment','0.7','177fd221356a829763d0519f193750f0d98b29368a978fc47f01980860d4bc73'), ('restaurant_partner','0.4','fc59b45ecb28ac9248b0bb45aeec72ae5c3c9baeeda51dd100c6ba33176171ea'), ('customer_terms','0.5','e59a905efc5013511e4959c78bd8c599b266adf5734aaad6cb43f44fda7a817e'), ('privacy_statement','0.6','7f8885e3f85a8a8b1c1be8cb1bc22a9bdabac6b360b5be01e4ee448d1bf3554f'), ('dpa_restaurant','0.4','d933a9d11651d17389a0b69ea86485211a0f109d7484e95df72e7f45ea379c01'), ('rider_conduct','0.3','64452e431fa9b7a2147feda388fc7754b120f383ab8cfc27408378ef02cac276'), ('platform_transparency','0.7','dd3f2cd8ba2abade35ac87cc21b4f85f2676730533b0391aaac734b0ac23a2e3'), ('dpia_gps','0.5','87361dc04ac92507212f34c8e4df26a9dcdc2c37299bc02378146effc8e16e9a'), ('processing_register','0.6','07bd57af7bf063102a152057242dc509b5175e735b91468e77c0c76dbc4f8a6c'), ('rider_onboarding','0.5','d01421c9aa21569bc80792cce269837fdfff7fc6563a01fe4eb46ae3a0a8f42c'), ('deactivation_appeal','0.3','6c4cf5864bea2631f47b3049207ca295a56f7720cc903734e571bef17d10afa5'), ('dpa_payroll','0.3','04b9cc62954ec9787335e3a9d409e979e82588aa20e69907c3a15524f96791c7')) n(id, version, sha) on true join public.legal_templates t on t.id = n.id and t.version = n.version
where p.role = 'rider' and p.is_test and t.id in ('rider_employment','rider_conduct','platform_transparency')
  and not exists (select 1 from public.legal_acceptances a where a.profile_id = p.id and a.template_id = t.id and a.version = t.version);
